# load data
data = {}
with open('data.csv') as f:
    rdr = csv.DictReader(f)
    for row in rdr:
        band = row['band']
        period = row['period_id']
        val = float(row['y'])
        data.setdefault(band, []).append((period, val))

# load visits to predict in order
visits = []
with open('visits_to_predict.csv') as f:
    rdr = csv.DictReader(f)
    for row in rdr:
        visits.append(row['period_id'])

