pred = {}
for band, records in data.items():
    # map period to value
    period_vals = {p:v for p,v in records}
    # ensure ordering of visits as given
    preds = {}
    seen_vals = []
    for vid in visits:
        # predict using mean of seen_vals (historical)
        if seen_vals:
            preds[vid] = sum(seen_vals)/len(seen_vals)
        else:
            preds[vid] = None
        # after predicting, if this visit exists in history, add its true value for future predictions
        if vid in period_vals:
            seen_vals.append(period_vals[vid])
    pred[band] = preds

# Build final JSON: only include predictions for visits (period_id) as top keys, each containing band values
final = {"prediction": {}}
for vid in visits:
    final["prediction"][vid] = {}
    for band in pred:
        val = pred[band][vid]
        if val is not None:
            final["prediction"][vid][band] = round(val,6)
# rationale
final["rationale"] = "Predicted each visit's band values as the mean of that band from all earlier observed visits of the same parcel."

# write answer.json
with open('answer.json','w') as f:
    json.dump(final, f, indent=2)
print(json.dumps(final))
